// JAH demo program — Visual disposition
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function visual(defects){ if(defects.critical>0) return 'reject';
  if(defects.major>0) return 'rework or concession'; if(defects.minor>2) return 'rework'; return 'accept'; }
check("critical defect", visual({critical:1,major:0,minor:0}), "reject");
check("one major", visual({critical:0,major:1,minor:0}), "rework or concession");
check("clean", visual({critical:0,major:0,minor:1}), "accept");
var __ok=true;
__checks.forEach(function(c){var ok=String(c[1])===String(c[2]);__ok=ok&&__ok;console.log((ok?"PASS":"FAIL")+" | "+c[0]+" => "+c[1]);});
console.log(__ok?"ALL CHECKS PASSED":"SOME CHECKS FAILED");
if(!__ok){throw new Error("demo self-check failed");}

