// JAH demo program — Control limits
"use strict";
var __checks=[];
function check(l,g,w){__checks.push([l,g,w]);}
function limits(mean, sigma){ return {lcl:mean-3*sigma, ucl:mean+3*sigma}; }
function cpk(mean, sigma, lsl, usl){ return Math.min((usl-mean),(mean-lsl))/(3*sigma); }
var L=limits(10,0.5);
check("UCL = 11.5", L.ucl, 11.5);
check("LCL = 8.5", L.lcl, 8.5);
check("Cpk 1.33+ is capable", cpk(10,0.5,8,12)>=1.33, true);
